"""GAP-A (unet-m2-s6): the AIE/CPU partition is generated by aiegraph.autopart, not hand-kept.

x86 only, real bk-sdm-tiny UNet ONNX (no TVM build, no board). Checks the three modes against the
P35x hand partition (example/aiegraph/unet_bk_sdm_tiny/partition.json) and kplan.py.
"""
import importlib.util
import json
import sys
from pathlib import Path

import pytest

SRC = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(SRC))

from aiegraph import autopart as apm  # noqa: E402
from aiegraph.plan import kincore_geom  # noqa: E402

UNET_ONNX = Path("/scratch/staff/huaj/modelzoo/artifacts/bk-sdm-tiny/unet_sim.onnx")
EX = SRC.parent / "example" / "aiegraph" / "unet_bk_sdm_tiny"
BASE = EX / "partition.json"
need_unet = pytest.mark.skipif(not UNET_ONNX.is_file() or not BASE.is_file(), reason="UNet ONNX not here")


def _kplan():
    spec = importlib.util.spec_from_file_location("kplan_ex", EX / "kplan.py")
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


@pytest.fixture(scope="module")
def model():
    import onnx
    return onnx.load(str(UNET_ONNX), load_external_data=False)


@pytest.fixture(scope="module")
def base():
    return json.loads(BASE.read_text())


@pytest.fixture(scope="module")
def parts(model, base):
    return {m: apm.autopartition(model, m, base=base, log=lambda *_: None) for m in apm.MODES}


# ── synthetic graph: classification, gemv, attn, M padding ────────────────────
def _tiny():
    import numpy as np
    import onnx
    from onnx import TensorProto, helper, numpy_helper
    W = numpy_helper.from_array(np.zeros((64, 128), np.float32), "W")
    T = numpy_helper.from_array(np.zeros((128, 64), np.float32), "T")
    C = numpy_helper.from_array(np.zeros((64, 64, 3, 3), np.float32), "C")
    nodes = [
        helper.make_node("Gemm", ["t", "T"], ["te"], name="/u/time_embedding/linear_1/Gemm"),
        helper.make_node("Conv", ["x", "C"], ["y"], name="/u/down_blocks.0/resnets.0/conv1/Conv",
                         pads=[1, 1, 1, 1]),
        helper.make_node("MatMul", ["h", "W"], ["q"], name="MatMul_0"),
        helper.make_node("MatMul", ["q", "k"], ["s"], name="/u/down_blocks.0/attentions.0/attn1/MatMul"),
    ]
    g = helper.make_graph(nodes, "tiny", [
        helper.make_tensor_value_info("t", TensorProto.FLOAT, [1, 128]),
        helper.make_tensor_value_info("x", TensorProto.FLOAT, [1, 64, 8, 8]),
        helper.make_tensor_value_info("h", TensorProto.FLOAT, [1, 77, 64]),
        helper.make_tensor_value_info("k", TensorProto.FLOAT, [1, 128, 77])],
        [helper.make_tensor_value_info(o, TensorProto.FLOAT, None) for o in ("te", "y", "s")],
        [W, T, C])
    return onnx.helper.make_model(g)


def test_inventory_classes():
    rows = {r["node"]: r for r in apm.inventory(_tiny())}
    assert rows["/u/time_embedding/linear_1/Gemm"]["cls"] == "gemv"
    assert rows["/u/down_blocks.0/resnets.0/conv1/Conv"]["cls"] == "conv"
    assert (rows["/u/down_blocks.0/resnets.0/conv1/Conv"]["m"], rows["/u/down_blocks.0/resnets.0/conv1/Conv"]["k"]) == (64, 576)
    assert rows["MatMul_0"]["cls"] == "linear" and rows["MatMul_0"]["m"] == 77
    assert rows["/u/down_blocks.0/attentions.0/attn1/MatMul"]["cls"] == "attn"


def test_tiny_all_mode_pads_m_only():
    d = apm.autopartition(_tiny(), "all", log=lambda *_: None)
    by = {l["node"]: l for l in d["layers"]}
    assert by["MatMul_0"]["mkn"] == [[128, 64, 128]] and by["MatMul_0"]["pad"]["M"] == 128
    assert by["MatMul_0"]["macs"] == 77 * 64 * 128                 # true MACs, not padded
    assert [l["cls"] for l in d["cpu_gemm_layers"]] == ["attn"]    # gemv is not a GEMM row
    assert d["total_gemm_macs"] == sum(l["macs"] for l in d["layers"]) + d["cpu_gemm_layers"][0]["macs"]


def test_l37_needs_base():
    with pytest.raises(apm.AiegraphError):
        apm.autopartition(_tiny(), "l37", log=lambda *_: None)


# ── real UNet ──────────────────────────────────────────────────────────────────
@need_unet
def test_parts_and_total_match_p35x(model, base):
    p = apm.assign_parts(model)
    bl = base["layers"] + base["cpu_gemm_layers"]
    assert all(p[l["node"]][0] == l["part"] for l in bl)
    d = apm.autopartition(model, "conv", log=lambda *_: None)
    assert d["total_gemm_macs"] == base["total_gemm_macs"] == 54392913920
    assert len(d["layers"]) + len(d["cpu_gemm_layers"]) == len(bl) == 158
    files = {(l["part"], l["file"]) for l in base["layers"]}
    assert {(l["part"], l["file"]) for l in d["layers"] if l["part"] in {q for q, _ in files}} <= files


@need_unet
def test_conv_mode(parts):
    d = parts["conv"]
    assert len(d["layers"]) == 48 and {l["cls"] for l in d["layers"]} == {"conv"}
    cpu = {l["node"]: l["why"] for l in d["cpu_gemm_layers"] if l["cls"] == "conv"}
    assert cpu == {"/u/conv_in/Conv": ["K%64"], "/u/conv_out/Conv": ["N%64"]}
    assert d["aie_flop_frac"] >= 0.62
    assert d["kincore_launches"] == 48


@need_unet
def test_hand_excludes_rechecked(parts, base):
    """P35x excluded parts 21/23 by hand and budget-cut 19/20/22: all their convs are legal now."""
    now = {l["node"] for l in parts["conv"]["layers"]}
    b = {l["node"] for l in base["layers"]}
    gen = {l["node"]: l["part"] for l in parts["conv"]["layers"]}
    assert b <= now
    assert sorted(gen[n] for n in now - b) == [19, 20, 20, 20, 21, 21, 22, 22, 22, 23, 23]


@need_unet
def test_l37_mode(parts, base):
    d = parts["l37"]
    assert {l["node"] for l in d["layers"] if l["cls"] == "conv"} == {l["node"] for l in base["layers"]}
    assert sum(l["cls"] == "linear" for l in d["layers"]) == 72
    assert sum(l["cls"] == "conv" for l in d["cpu_gemm_layers"]) == 13
    assert d["aie_flop_frac"] >= 0.73


@need_unet
def test_all_mode_and_splits(parts):
    d = parts["all"]
    assert sum(l["cls"] == "conv" for l in d["layers"]) == 48
    assert sum(l["cls"] == "linear" for l in d["layers"]) == 72
    assert all(l["cls"] == "attn" for l in d["cpu_gemm_layers"] if l["cls"] != "conv")
    assert d["aie_flop_frac"] >= 0.90
    by = {l["node"]: l for l in d["layers"]}
    assert by["MatMul_0"]["mkn"] == [[1024, 320, 320]] * 3        # fused QKV 960 -> 3 launches
    assert by["Gemm_9"]["pad"]["nsplit"] >= 2
    kv = [l for l in d["layers"] if l.get("pad", {}).get("M") == 128]
    assert len(kv) == 18 and all(l["pad"]["orig"][0] == 77 for l in kv)


@need_unet
@pytest.mark.parametrize("mode", apm.MODES)
def test_every_launch_legal(parts, mode):
    kp = _kplan()
    for l in parts[mode]["layers"]:
        for m, k, n in l["mkn"]:
            assert kp.plan(m, k, n)["legal"], (l["node"], m, k, n)
            assert kincore_geom(n, k, m)["legal"], (l["node"], m, k, n)
        assert sum(a * b * c for a, b, c in l["mkn"]) >= l["macs"]


@need_unet
def test_cli(tmp_path, base):
    from aiegraph.__main__ import main
    out = tmp_path / "p.json"
    assert main(["autopart", "--onnx", str(UNET_ONNX), "--base", str(BASE), "--mode", "conv",
                 "--out", str(out)]) == 0
    d = json.loads(out.read_text())
    assert d["N"] == sum(l["launches"] for l in d["layers"]) and len(d["layers"]) == 48
